<?php
declare(strict_types=1);session_start();require __DIR__.'/config.local.php';header('Content-Type: application/json; charset=utf-8');
try{$pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$trip=(int)($_POST['trip_id']??0);$seat=(int)($_POST['seat_id']??0);$token=bin2hex(random_bytes(16));$pdo->beginTransaction();$q=$pdo->prepare('SELECT status,(hold_until IS NOT NULL AND hold_until<=NOW()) AS hold_expired FROM trip_seats WHERE id=? AND trip_id=? FOR UPDATE');$q->execute([$seat,$trip]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row||($row['status']!=='available'&&!($row['status']==='held'&&(int)$row['hold_expired']===1)))throw new RuntimeException('Ese asiento ya está reservado o vendido.');$pdo->prepare("UPDATE trip_seats SET status='held',hold_token=?,hold_until=DATE_ADD(NOW(),INTERVAL 10 MINUTE) WHERE id=?")->execute([$token,$seat]);$pdo->commit();$_SESSION['seat_hold'][(string)$seat]=$token;echo json_encode(['ok'=>true,'token'=>$token,'expires_in'=>600]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();http_response_code(409);echo json_encode(['ok'=>false,'message'=>$e instanceof RuntimeException?$e->getMessage():'No se pudo reservar el asiento.']);}
